import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Product {
  id: string;
  name: string;
  price: string;
  brand: string;
  thumbnail: string; // URL for the circular icon
  description: string; // Prompt for the AI
  category: 'shirt' | 'hoodie' | 'jacket' | 'polo';
  color: string;
}

export interface GeneratedResult {
  imageUrl: string;
  productId: string;
}

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateTryOn = async (
  base64Image: string,
  productDescription: string
): Promise<string> => {
  try {
    // Strip the data URL prefix if present to get just the base64 string
    const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg);base64,/, '');

    const prompt = `Edit this image. Replace the person's upper body clothing with ${productDescription}. 
    Ensure the clothing fits naturally on the person's body, matching their pose and lighting. 
    Keep the person's face, hair, skin tone, and the background exactly as they are. 
    Output a high-quality photorealistic image.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            text: prompt,
          },
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64,
            },
          },
        ],
      },
    });

    // Check for inline data (image) response
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData && part.inlineData.data) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image generated");
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

import React, { useRef, useEffect, forwardRef, useImperativeHandle } from 'react';

interface CameraViewProps {
  onStreamReady?: () => void;
  isActive: boolean;
}

export interface CameraHandle {
  capture: () => string | null;
}

const CameraView = forwardRef<CameraHandle, CameraViewProps>(({ onStreamReady, isActive }, ref) => {
  const videoRef = useRef<HTMLVideoElement>(null);

  useImperativeHandle(ref, () => ({
    capture: () => {
      if (!videoRef.current) return null;
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth;
      canvas.height = videoRef.current.videoHeight;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        // Mirror the capture if the video is mirrored
        ctx.translate(canvas.width, 0);
        ctx.scale(-1, 1);
        ctx.drawImage(videoRef.current, 0, 0);
        return canvas.toDataURL('image/jpeg', 0.8);
      }
      return null;
    }
  }));

  useEffect(() => {
    let stream: MediaStream | null = null;

    const startCamera = async () => {
      try {
        stream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode: 'user',
            width: { ideal: 1280 },
            height: { ideal: 720 },
          },
          audio: false,
        });

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.onloadedmetadata = () => {
            videoRef.current?.play();
            onStreamReady?.();
          };
        }
      } catch (err) {
        console.error("Error accessing camera:", err);
      }
    };

    if (isActive) {
      startCamera();
    }

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [isActive, onStreamReady]);

  return (
    <div className="absolute inset-0 bg-black z-0">
      <video
        ref={videoRef}
        className="w-full h-full object-cover transform -scale-x-100"
        playsInline
        muted
        autoPlay
      />
    </div>
  );
});

export default CameraView;

