import React, { useState, useRef, useCallback } from 'react';
import CameraView, { CameraHandle } from './components/CameraView';
import UIOverlay from './components/UIOverlay';
import { PRODUCTS } from './constants';
import { Product } from './types';
import { generateTryOn } from './services/gemini';
import { Sparkles } from 'lucide-react';

const App: React.FC = () => {
  const cameraRef = useRef<CameraHandle>(null);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleProductSelect = useCallback(async (product: Product) => {
    if (selectedProduct?.id === product.id && generatedImage) return; // Already viewing this

    setSelectedProduct(product);
    setGeneratedImage(null); // Clear previous result while keeping product selected to show card
    setError(null);

    // 1. Capture current frame
    const imageBase64 = cameraRef.current?.capture();

    if (!imageBase64) {
      setError("Could not capture camera frame.");
      return;
    }

    // 2. Start processing
    setIsProcessing(true);

    try {
      // 3. Call Gemini API
      const resultImage = await generateTryOn(imageBase64, product.description);
      setGeneratedImage(resultImage);
    } catch (err) {
      console.error(err);
      setError("Failed to generate try-on. Please try again.");
      // Reset after a moment so user can try again
      setTimeout(() => setSelectedProduct(null), 3000);
    } finally {
      setIsProcessing(false);
    }
  }, [selectedProduct, generatedImage]);

  const handleReset = useCallback(() => {
    setSelectedProduct(null);
    setGeneratedImage(null);
    setError(null);
  }, []);

  return (
    <div className="relative w-full h-dvh bg-black overflow-hidden font-sans">

      {/* 1. Camera Feed (Background) */}
      <CameraView 
        ref={cameraRef} 
        isActive={!generatedImage} 
      />

      {/* 2. Generated Image Layer (Visible when result exists) */}
      {generatedImage && (
        <div className="absolute inset-0 z-0 animate-in fade-in duration-700">
           <img 
             src={generatedImage} 
             alt="Virtual Try-On Result" 
             className="w-full h-full object-cover"
           />
           {/* Watermark/Label to indicate AI generation */}
           <div className="absolute top-20 left-4 bg-black/40 backdrop-blur-md border border-white/20 px-3 py-1 rounded-full flex items-center gap-2">
             <Sparkles className="w-3 h-3 text-yellow-400" />
             <span className="text-[10px] font-medium text-white/90">AI Generated</span>
           </div>
        </div>
      )}

      {/* 3. Processing State Overlay (Glass blur effect) */}
      {isProcessing && (
        <div className="absolute inset-0 z-0 bg-black/20 backdrop-blur-sm flex items-center justify-center">
            {/* Visual cue handled by UIOverlay button, but this layer prevents interaction with video */}
        </div>
      )}

      {/* 4. Error Toast */}
      {error && (
        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-red-500/90 text-white px-6 py-3 rounded-xl shadow-2xl z-50 text-sm font-bold animate-bounce">
          {error}
        </div>
      )}

      {/* 5. Main UI Layer */}
      <UIOverlay 
        products={PRODUCTS}
        selectedProduct={selectedProduct}
        isProcessing={isProcessing}
        onSelectProduct={handleProductSelect}
        onReset={handleReset}
        hasResult={!!generatedImage}
      />
    </div>
  );
};

export default App;

