import React, { useRef, useEffect, forwardRef, useImperativeHandle } from 'react';

interface CameraViewProps {
  onStreamReady?: () => void;
  isActive: boolean;
}

export interface CameraHandle {
  capture: () => string | null;
}

const CameraView = forwardRef<CameraHandle, CameraViewProps>(({ onStreamReady, isActive }, ref) => {
  const videoRef = useRef<HTMLVideoElement>(null);

  useImperativeHandle(ref, () => ({
    capture: () => {
      if (!videoRef.current) return null;

      // Ensure we have dimensions
      const width = videoRef.current.videoWidth;
      const height = videoRef.current.videoHeight;

      if (width === 0 || height === 0) return null;

      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        // Mirror the capture if the video is mirrored
        ctx.translate(canvas.width, 0);
        ctx.scale(-1, 1);
        ctx.drawImage(videoRef.current, 0, 0);
        return canvas.toDataURL('image/jpeg', 0.8);
      }
      return null;
    }
  }));

  useEffect(() => {
    let stream: MediaStream | null = null;

    const startCamera = async () => {
      try {
        // We remove ideal width/height to ensure this works on all devices (avoiding OverconstrainedError)
        stream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode: 'user',
          },
          audio: false,
        });

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          // onloadedmetadata is crucial to know when video dimensions are ready
          videoRef.current.onloadedmetadata = () => {
            videoRef.current?.play().catch(e => console.error("Play error:", e));
            onStreamReady?.();
          };
        }
      } catch (err) {
        console.error("Error accessing camera:", err);
      }
    };

    if (isActive) {
      startCamera();
    }

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [isActive, onStreamReady]);

  return (
    <div className="absolute inset-0 bg-black z-0">
      <video
        ref={videoRef}
        className="w-full h-full object-cover transform -scale-x-100"
        playsInline
        muted
        autoPlay
      />
    </div>
  );
});

export default CameraView;

import React, { useState, useRef, useCallback } from 'react';
import CameraView, { CameraHandle } from './components/CameraView';
import UIOverlay from './components/UIOverlay';
import { PRODUCTS } from './constants';
import { Product } from './types';
import { generateTryOn } from './services/gemini';
import { Sparkles } from 'lucide-react';

const App: React.FC = () => {
  const cameraRef = useRef<CameraHandle>(null);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleProductSelect = useCallback(async (product: Product) => {
    if (selectedProduct?.id === product.id && generatedImage) return; // Already viewing this

    setSelectedProduct(product);
    setGeneratedImage(null); // Clear previous result while keeping product selected to show card
    setError(null);

    // 1. Capture current frame
    // Small delay to ensure state updates don't conflict with capture if needed, 
    // though usually immediate capture is fine.
    const imageBase64 = cameraRef.current?.capture();

    if (!imageBase64) {
      console.error("Camera capture failed - video might not be ready");
      setError("Could not capture camera. Please ensure camera is on.");
      return;
    }

    // 2. Start processing
    setIsProcessing(true);

    try {
      // 3. Call Gemini API
      const resultImage = await generateTryOn(imageBase64, product.description);
      setGeneratedImage(resultImage);
    } catch (err: any) {
      console.error(err);
      // Show more descriptive error if available
      const errorMessage = err?.message || "Failed to generate try-on. Please try again.";
      setError(errorMessage);

      // Reset after a moment so user can try again
      setTimeout(() => {
        setSelectedProduct(null);
        setError(null);
      }, 4000);
    } finally {
      setIsProcessing(false);
    }
  }, [selectedProduct, generatedImage]);

  const handleReset = useCallback(() => {
    setSelectedProduct(null);
    setGeneratedImage(null);
    setError(null);
  }, []);

  return (
    <div className="relative w-full h-dvh bg-black overflow-hidden font-sans">

      {/* 1. Camera Feed (Background) */}
      <CameraView 
        ref={cameraRef} 
        isActive={!generatedImage} 
      />

      {/* 2. Generated Image Layer (Visible when result exists) */}
      {generatedImage && (
        <div className="absolute inset-0 z-0 opacity-0 animate-[fadeIn_0.7s_ease-out_forwards]">
           <img 
             src={generatedImage} 
             alt="Virtual Try-On Result" 
             className="w-full h-full object-cover"
           />
           {/* Watermark/Label to indicate AI generation */}
           <div className="absolute top-20 left-4 bg-black/40 backdrop-blur-md border border-white/20 px-3 py-1 rounded-full flex items-center gap-2">
             <Sparkles className="w-3 h-3 text-yellow-400" />
             <span className="text-[10px] font-medium text-white/90">AI Generated</span>
           </div>
        </div>
      )}

      {/* 3. Processing State Overlay (Glass blur effect) */}
      {isProcessing && (
        <div className="absolute inset-0 z-0 bg-black/20 backdrop-blur-sm flex items-center justify-center">
            {/* Visual cue handled by UIOverlay button, but this layer prevents interaction with video */}
        </div>
      )}

      {/* 4. Error Toast */}
      {error && (
        <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-4/5 max-w-sm bg-red-600/90 backdrop-blur-md text-white px-6 py-4 rounded-xl shadow-2xl z-50 text-sm font-medium text-center animate-bounce">
          {error}
        </div>
      )}

      {/* 5. Main UI Layer */}
      <UIOverlay 
        products={PRODUCTS}
        selectedProduct={selectedProduct}
        isProcessing={isProcessing}
        onSelectProduct={handleProductSelect}
        onReset={handleReset}
        hasResult={!!generatedImage}
      />

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
      `}</style>
    </div>
  );
};

export default App;

