import React, { useRef, useEffect, forwardRef, useImperativeHandle } from 'react';

interface CameraViewProps {
  onStreamReady?: () => void;
  isActive: boolean;
}

export interface CameraHandle {
  capture: () => string | null;
}

const CameraView = forwardRef<CameraHandle, CameraViewProps>(({ onStreamReady, isActive }, ref) => {
  const videoRef = useRef<HTMLVideoElement>(null);

  useImperativeHandle(ref, () => ({
    capture: () => {
      if (!videoRef.current) return null;

      // Ensure we have dimensions
      const width = videoRef.current.videoWidth;
      const height = videoRef.current.videoHeight;

      if (width === 0 || height === 0) return null;

      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        // Mirror the capture if the video is mirrored
        ctx.translate(canvas.width, 0);
        ctx.scale(-1, 1);
        ctx.drawImage(videoRef.current, 0, 0);
        return canvas.toDataURL('image/jpeg', 0.9); // Slightly higher quality for better AI details
      }
      return null;
    }
  }));

  useEffect(() => {
    let stream: MediaStream | null = null;

    const startCamera = async () => {
      try {
        // Request higher resolution (Full HD) to improve detail when subject is far away
        // "ideal" constraint prevents errors on devices that don't support it (falls back gracefully)
        stream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode: 'user',
            width: { ideal: 1920 }, 
            height: { ideal: 1080 }
          },
          audio: false,
        });

        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          // onloadedmetadata is crucial to know when video dimensions are ready
          videoRef.current.onloadedmetadata = () => {
            videoRef.current?.play().catch(e => console.error("Play error:", e));
            onStreamReady?.();
          };
        }
      } catch (err) {
        console.error("Error accessing camera:", err);
      }
    };

    if (isActive) {
      startCamera();
    }

    return () => {
      if (stream) {
        stream.getTracks().forEach(track => track.stop());
      }
    };
  }, [isActive, onStreamReady]);

  return (
    <div className="absolute inset-0 bg-black z-0">
      <video
        ref={videoRef}
        className="w-full h-full object-cover transform -scale-x-100"
        playsInline
        muted
        autoPlay
      />
    </div>
  );
});

export default CameraView;

import { GoogleGenAI } from "@google/genai";

export const generateTryOn = async (
  base64Image: string,
  productDescription: string
): Promise<string> => {
  try {
    // Initialize inside the function to avoid top-level ReferenceError if process is not defined immediately
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Strip the data URL prefix if present to get just the base64 string
    const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg);base64,/, '');

    const prompt = `Edit this image to show the person wearing a new outfit.
    Replace the person's current top/upper body clothing with: ${productDescription}.

    CRITICAL INSTRUCTIONS:
    1. Accurately detect the person's body, even if they are standing far away or only partially visible.
    2. Map the new clothing perfectly to their body shape, pose, and perspective.
    3. Ensure realistic fabric folds, lighting, and shadows that match the original scene.
    4. Do NOT modify the person's face, hair, skin tone, hands, or the background.

    Output a high-quality, photorealistic image.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: cleanBase64,
            },
          },
          {
            text: prompt,
          },
        ],
      },
    });

    // Check for inline data (image) response
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData && part.inlineData.data) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image generated by the model.");
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
};

